(*----- Function toLit -----*)

Definition toLit_safety_wit_1 :=
forall (v_pre: Z) (PreH1 : (0 <= v_pre)) (PreH2 : ((v_pre + v_pre ) <= INT_MAX)),
  ((( &( "v" ) )) # Int  |-> v_pre)
|--
  “ ((v_pre + v_pre ) <= INT_MAX) ”
  &&  “ ((INT_MIN) <= (v_pre + v_pre )) ”
.

Definition toLit_return_wit_1 :=
forall (v_pre: Z) (PreH1 : (0 <= v_pre)) (PreH2 : ((v_pre + v_pre ) <= INT_MAX)),
  TT && emp 
|--
  “ ((v_pre + v_pre ) = (v_pre + v_pre )) ”
  &&  emp
.

