Definition lit_var_safety_wit_1_original :=
forall (l_pre: Z) (PreH1 : (0 <= l_pre)) (PreH2 : (l_pre <= INT_MAX)),
  ((( &( "l" ) )) # Int  |-> l_pre)
|--
  “ (0 <= l_pre) ”
  &&  “ (1 <= 31) ”
  &&  “ (0 <= 1) ”
.

Definition lit_var_safety_wit_2_zero_index :=
forall (lv_assigns_zero_index: (@list Z)) (lv_asg_zero_index: Z) (l_pre: Z) (PreH1 : (0 <= l_pre)) (PreH2 : (l_pre < (2 * (Zlength (lv_assigns_zero_index)) ))) (PreH3 : ((2 * (Zlength (lv_assigns_zero_index)) ) <= INT_MAX)) (PreH4 : ((Znth ((lit_var_c (l_pre))) (lv_assigns_zero_index) (0)) = 0)),
  ((( &( "l" ) )) # Int  |-> l_pre)
  **  (((lv_asg_zero_index + ((lit_var_c (l_pre)) * sizeof(CHAR)))) # Char  |-> (Znth ((lit_var_c (l_pre))) (lv_assigns_zero_index) (0)))
  **  (CharArray.missing_i lv_asg_zero_index (lit_var_c (l_pre)) 0 (Zlength (lv_assigns_zero_index)) lv_assigns_zero_index )
|--
  “ (0 <= l_pre) ”
  &&  “ (1 <= 31) ”
  &&  “ (0 <= 1) ”
.

