(
forall (lv_assigns_zero_index: (@list Z)) (lv_asg_zero_index: Z) (l_pre: Z) (PreH1 : (0 <= l_pre)) (PreH2 : (l_pre < (2 * (Zlength (lv_assigns_zero_index)) ))) (PreH3 : ((2 * (Zlength (lv_assigns_zero_index)) ) <= INT_MAX)) (PreH4 : ((Znth ((lit_var_c (l_pre))) (lv_assigns_zero_index) (0)) = 0)),
