  &&  “ ((Z.shiftr l_pre 1) < (Zlength (lv_assigns_zero_index))) ”
  &&  “ (0 <= (Z.shiftr l_pre 1)) ”
  &&  “ ((Z.shiftr l_pre 1) = (lit_var_c (l_pre))) ”
